  FT["PH-H9406"] = {"id":"PH-H9406","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2017/ra_10959_2017.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"设立Capas市","en":"An Act Creating a Barangay to Be Known as Barangay Cristo Rey in the Municipality of Capas, Province of Tarlac","orig":"An Act Creating a Barangay to Be Known as Barangay Cristo Rey in the Municipality of Capas, Province of Tarlac"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 10959","issuingBody":"Congress of the Philippines","promulgatedDate":"2017-11-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2017/ra_10959_2017.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9406-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation of Barangay Cristo Rey. - The O’Donnel Resettlement Area in Barangay Aranguren, Municipality of Capas, Province of Tarlac which was separated from Barangay Aranguren and constituted as a distinct and independent barangay under Provincial Ordinance No. 004-2003 in 2003 is hereby created and shall hereafter be known as Barangay Cristo Rey."}},{"id":"PH-H9406-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Territorial Boundaries. - The territorial boundaries of Barangay Cristo Rey shall be identified as follows:\nBounded on the Northwest (NW) and Northeast (NE) pts 1 to 4 and 16 by Capas Cadastre CAD 615-D Case 11 Barangay Lawy (PB-03-000024-D);\nOn the Northeast (NE) pts 4 and 5 by Capas Cadastre CAD 615-D Case 12 Barangay Aranguren (PB-03-000024-D);\nOn the Southeast (SE) and Southwest (SW) pts 5 to 15 by provincial road;\nOn the Southwest (SW) along line 15 .to -16 by Capas Cadastre CAD 615-D Case 12 Barangay Aranguren (PB-03-000024-D), all of Municipality of Capas.\nThe technical description of Barangay Cristo Rey is as follows:\nTIEPOINT 1 N 03 15 W\n842.16 BLLM # 1-A, CAD 615-D, Capas Cadastre 1 2 N 73 13 E 1,703.55 2 3 S 02 58 E\n939.78 3 4 S 04 08 W\n362.82 4 5 S 02 18 E\n444.99 5 6 S 74 02 W\n121.73 6 7 S 74 45 W\n145.10 7 8 S 60 51 W\n283.14 8 9 S 72 49 W\n210.38 9 10 N 89 18 W\n936.67 10 11 N 82 26 W\n28.07 11 12 N 82 31 W\n203.36 12 13 N 67 28 W\n152.21 13 14 N 45 49 W\n146.23 14 15 N 22 22 W\n128.35 15 16 N 04 31 E 1,088.96 16 1 N 73 47 E\n425.36 Containing an area of 3,472,507 square meters, more or less."}},{"id":"PH-H9406-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Conduct and Supervision of Plebiscite. - The plebiscite conducted and supervised by the Commission on Elections (COMELEC) in Barangay Aranguren on December 13, 2003 pursuant to Provincial Ordinance No. 004-2003 of the Sangguniang Panlalawigan of the Province of Tarlac, which ratified the creation of Barangay Cristo Rey, shall serve as substantial compliance with the plebiscite requirement under Section 10 of Republic Act No. 7160, as amended, otherwise known as the \"Local Government Code of 1991 \"."}},{"id":"PH-H9406-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Incumbent Barangay Officials. - The incumbent barangay officials of Barangay Cristo Rey shall continue to hold office until such time that their successors have been duly elected and qualified."}},{"id":"PH-H9406-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Public Infrastructure and Facilities. - All public infrastructure and facilities for public use existing therein at the time of the approval of this Act are hereby transferred without cost or compensation to and shall be administered by the new barangay."}},{"id":"PH-H9406-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Internal Revenue Allotment Shares. - Barangay Cristo Rey shall be entitled to Internal Revenue Allotment (IRA) shares pursuant to Section 285 of Republic Act No. 7160, as amended, otherwise known as the \"Local Government Code of 1991\"."}},{"id":"PH-H9406-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p134"};
  FT["PH-H9407"] = {"id":"PH-H9407","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2017/ra_10960_2017.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"设立Titay市","en":"An Act Creating a Barangay to Be Known as Barangay San Isidro in the Municipality of Titay, Province of Zamboanga Sibugay","orig":"An Act Creating a Barangay to Be Known as Barangay San Isidro in the Municipality of Titay, Province of Zamboanga Sibugay"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 10960","issuingBody":"Congress of the Philippines","promulgatedDate":"2017-11-08","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2017/ra_10960_2017.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9407-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation of Barangay San Isidro. - There is hereby created a barangay to be known as Barangay San Isidro in the Municipality of Titay, Province of Zamboanga Sibugay."}},{"id":"PH-H9407-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Territorial Boundaries. - The territorial boundaries of Barangay San Isidro shall be identified as follows:\nBounded on the Northwest (NW), along line 1-2, by Barangay San Antonio;\nOn the Northeast (NE), along lines 2-3-4, by Barangay San Antonio; along lines 4-5-6, by Municipality of Ipil versus Titay, Zamboanga Sibugay; along line 6-7, by Municipality of Ipil, Zamboanga Sibugay;\nOn the Southeast (SE), along lines 7-8-9-10, by Municipality of Ipil, Zamboanga Sibugay;\nOn the Southwest (SW), along lines 10-11-12, by Municipality of RT Lim, Zamboanga Sibugay;\nOn the West (W), along line 12-1 to the point of beginning, by Barangay San Antonio versus Dalisay, all of Titay Municipality.\nBeginning at a point marked corner \"1\" = BLLM #1, CAD 1130-D, Titay Cadastre:\nLINE\nBEARING\nDISTANCE\nBLLM NO. 1-1 S53-54W 11,866.318m Thence 1-2 N62-43E\n863.84m.\nThence 2-3 S44-25E\n493.18m Thence 3-4 S57-15E 1,928.84m Thence 4-5 S57-15E\n233.58m Thence 5-6 S12-07E\n412.65m Thence 6-7 N82-41W 92420m Thence 7-8 S04-10E 2,131.40m Thence 8-9 S38-18W 1,133.67m Thence 9-10 S52-19W\n605.81m Thence 10-11 S88-49W 1,845.26m Thence 11-12 N80-13W 2,182.13m Thence 12-1 N33-10E 5,336.45m to the point of beginning;\nContaining an area of 17,475,340 square meters, more or less."}},{"id":"PH-H9407-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Conduct and Supervision of Plebiscite. - The plebiscite conducted and supervised by the Commission on Elections (COMELEC) pursuant to Provincial Ordinance No: 2002-122 dated August 7, 2002 of the Sangguniang Panlalawigan of the Province of Zamboanga Sibugay, which ratified the creation of Barangay San Isidro as proclaimed by the Plebiscite Board of Canvassers on April 16, 2005, shall serve as substantial compliance with the plebiscite requirement under Section 10 of Republic Act No. 7160, as amended, otherwise known as the \"Local Government Code of 1991\"."}},{"id":"PH-H9407-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Incumbent Barangay Officials. - The incumbent barangay officials of Barangay San Isidro shall continue to hold office until such time that their successors have been duly elected and qualified."}},{"id":"PH-H9407-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Public Infrastructure and Facilities. - All public infrastructure and facilities for public use existing therein at the time of the approval of this Act are hereby transferred without cost or compensation to and shall be administered by the new barangay."}},{"id":"PH-H9407-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Internal Revenue Allotment Shares. - Barangay San Isidro shall be entitled to Internal Revenue Allotment (IRA) shares pursuant to Section 285 of Republic Act No. 7160, as amended, otherwise known as the \" Local Government Code of 1991 \"."}},{"id":"PH-H9407-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p134"};
